import { processBatch } from '../src/ingest.mjs';

const args = process.argv.slice(2);
if (args.length < 3 || args.length > 4) {
  console.error('Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]');
  process.exitCode = 1;
